import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.Dw7N76_O.js";const p=JSON.parse('{"title":"English source: conventions and translator notes","description":"","frontmatter":{},"headers":[],"relativePath":"i18n/glossary/en.md","filePath":"i18n/glossary/en.md"}'),r={name:"i18n/glossary/en.md"};function s(n,e,i,c,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="english-source-conventions-and-translator-notes" tabindex="-1">English source: conventions and translator notes <a class="header-anchor" href="#english-source-conventions-and-translator-notes" aria-label="Permalink to &quot;English source: conventions and translator notes&quot;">​</a></h1><p>English is the source language: every other language translates from it. This page holds the rules every translation follows and a note for each message whose meaning isn&#39;t obvious from the English alone. Fink shows only the id and the text, so look an id up here when in doubt.</p><h2 id="how-a-message-is-written" tabindex="-1">How a message is written <a class="header-anchor" href="#how-a-message-is-written" aria-label="Permalink to &quot;How a message is written&quot;">​</a></h2><ul><li><strong>Ids</strong> are <code>&lt;group&gt;.&lt;camelCaseName&gt;</code>: the group is the screen or area (<code>library.sortPlanned</code>, <code>muscle.chest</code>). Catalog ids are <code>&lt;slug&gt;.&lt;field&gt;</code>, with <code>&lt;slug&gt;.instructions.&lt;n&gt;</code> for each instruction in order. No id is the prefix of another.</li><li><strong>Placeholders</strong> are named ICU arguments. <code>{name}</code> is text, <code>{count, number}</code> is a whole number. Keep every placeholder of the English, with the same name; move it wherever the sentence needs it.</li><li><strong>Plurals</strong> are ICU <code>plural</code>: <code>{count, plural, one {# session} other {# sessions}}</code>. <code>#</code> is the number. Give every form your language needs (French: <code>one</code>, <code>many</code>, <code>other</code>); Fink lists them.</li><li><strong>Apostrophes, ellipses and spaces</strong> need no care: type &#39; and ... as usual. After each merge they become ’ and …, and the non-breaking spaces a language needs are added (French: before <code>: ; ! ? %</code> and inside « »).</li><li><strong>Product names</strong> stay as they are: Coach Poulpy, Poulpy.</li></ul><h2 id="namespaces" tabindex="-1">Namespaces <a class="header-anchor" href="#namespaces" aria-label="Permalink to &quot;Namespaces&quot;">​</a></h2><p>Fink groups messages in three namespaces:</p><table tabindex="0"><thead><tr><th>Namespace</th><th>What it holds</th></tr></thead><tbody><tr><td><code>app</code></td><td>The app’s screens</td></tr><tr><td><code>domain</code></td><td>Words shown everywhere: muscles, equipment, units, workout types, step roles, Poulpy’s lines</td></tr><tr><td><code>catalog</code></td><td>Exercise names, instructions, variation notes and search aliases</td></tr></tbody></table><h2 id="translator-notes" tabindex="-1">Translator notes <a class="header-anchor" href="#translator-notes" aria-label="Permalink to &quot;Translator notes&quot;">​</a></h2><p>Messages not listed here mean what their English says.</p><h3 id="app" tabindex="-1">app <a class="header-anchor" href="#app" aria-label="Permalink to &quot;app&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Id</th><th>Note</th></tr></thead><tbody><tr><td><code>app.name</code></td><td>The product name. Never translated.</td></tr><tr><td><code>common.loading</code></td><td>Spoken by screen readers while a screen loads; never seen.</td></tr><tr><td><code>tab.*</code></td><td>Tab labels at the bottom of the screen: about 12 characters fit before the text shrinks. One word is best.</td></tr><tr><td><code>tab.live</code></td><td>The tab for a session recorded from connected devices (treadmill, heart rate band), as it happens.</td></tr><tr><td><code>home.inDays</code></td><td><code>{date}</code> is a weekday and date, already formatted for the language.</td></tr><tr><td><code>library.sort</code></td><td>iOS only: the label of the sort menu.</td></tr><tr><td><code>library.all</code>, <code>exercises.all</code></td><td>Filter chip that clears the filter. Agrees with “workouts” and “exercises” respectively.</td></tr><tr><td><code>library.planned</code>, <code>library.lastDone</code>, <code>workout.planned</code>, <code>history.todayDay</code></td><td><code>{date}</code> is a short date or “today”, already formatted.</td></tr><tr><td><code>exercise.variationPosition</code>, <code>exercise.variationsA11y</code></td><td><code>{position}</code> is already formatted, like “2 of 5”.</td></tr><tr><td><code>builder.less</code>, <code>builder.more</code></td><td>iOS only: buttons that lower or raise a value. Android uses <code>builder.lessNamed</code>/<code>builder.moreNamed</code>, where <code>{label}</code> names the value.</td></tr><tr><td><code>builder.open</code>, <code>builder.moreActions</code></td><td>Accessibility labels; <code>{name}</code> is the step’s name.</td></tr><tr><td><code>builder.editValue</code></td><td>Accessibility label for typing a value; <code>{label}</code> names it (sets, weight…).</td></tr><tr><td><code>builder.repeat</code>, <code>builder.addRepeat</code></td><td>A repeat is a group of steps done several times in a row, like intervals. Not “repetition” of a single movement (that is a rep).</td></tr><tr><td><code>builder.untilPressed</code>, <code>builder.untilEnd</code></td><td>A step with no set length: it lasts until the person presses the button, or, on the last step, until the session ends.</td></tr><tr><td><code>player.summary</code></td><td><code>{duration}</code> is already formatted, like “24 min”.</td></tr><tr><td><code>treadmill.phase</code></td><td>A block is one part of a treadmill program, like “5 min at 8 km/h”.</td></tr><tr><td><code>treadmill.targetSpeed</code>, <code>treadmill.remaining</code></td><td><code>{speed}</code> and <code>{time}</code> are already formatted with their unit.</td></tr><tr><td><code>history.sessionsUnit</code></td><td>The word alone, shown under a big number.</td></tr><tr><td><code>history.tentaclesLit</code></td><td>Out of Poulpy’s eight tentacles; see the Poulpy notes below.</td></tr><tr><td><code>live.waitingBody</code>, <code>live.connectingOne</code>, <code>devices.forgetTitle</code>, <code>devices.usedInstead</code></td><td><code>{name}</code> is a device’s name.</td></tr><tr><td><code>live.finishStillBody</code>, <code>live.finishStoppedBody</code>, <code>live.finishLostBody</code></td><td><code>{endTime}</code> is a clock time, already formatted.</td></tr><tr><td><code>live.finishClosedBody</code></td><td><code>{endTime}</code> is how far into the session it stopped, like “12:40”, already formatted.</td></tr><tr><td><code>live.notificationPaused</code></td><td><code>{elapsed}</code> is the time recorded so far, like “12:40”.</td></tr><tr><td><code>devices.openSettings</code></td><td>iOS only: opens the phone’s Settings app. Use the name the phone uses.</td></tr><tr><td><code>devices.allowBluetooth</code></td><td>Android only.</td></tr><tr><td><code>kind.footPod</code></td><td>A small sensor clipped to the shoe that measures pace and cadence.</td></tr><tr><td><code>settings.languageNextLaunch</code></td><td>iOS only.</td></tr></tbody></table><h3 id="domain" tabindex="-1">domain <a class="header-anchor" href="#domain" aria-label="Permalink to &quot;domain&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Id</th><th>Note</th></tr></thead><tbody><tr><td><code>muscleArea.*</code></td><td>Broad body areas for filter chips; shorter than <code>muscle.*</code>.</td></tr><tr><td><code>pattern.*</code></td><td>Movement patterns, the families exercises are grouped in. <code>pattern.hinge</code> bends at the hips with a flat back. <code>pattern.carry</code> walks holding a load.</td></tr><tr><td><code>role.*</code></td><td>The tag on a step in a workout. <code>role.recover</code> is easy effort between hard efforts, not a full stop.</td></tr><tr><td><code>label.session</code></td><td>Shown for a session whose workout was deleted.</td></tr><tr><td><code>label.or</code>, <code>label.and</code></td><td>Join filter labels: “Dumbbells or kettlebell”.</td></tr><tr><td><code>label.demoIntervals</code></td><td>The name of a built-in treadmill program for trying the app.</td></tr><tr><td><code>count.position</code></td><td>“3 of 5”, used in many places.</td></tr><tr><td><code>unit.*</code></td><td>Unit formats. <code>unit.minutesSeconds</code> and <code>unit.hoursMinutes</code>: the second argument is already two digits (“1 h 05”).</td></tr><tr><td><code>workout.deleteTitle</code></td><td><code>{name}</code> is the workout’s name, chosen by the person.</td></tr><tr><td><code>poulpy.*</code></td><td>Poulpy, the octopus mascot, speaking in the first person. He lights one of his eight tentacles per finished session; eight make a full octopus. He is warm and never guilt-trips. His voice is described on the <a href="./../../docs/brand">brand</a> page.</td></tr></tbody></table><h3 id="catalog" tabindex="-1">catalog <a class="header-anchor" href="#catalog" aria-label="Permalink to &quot;catalog&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Id</th><th>Note</th></tr></thead><tbody><tr><td><code>&lt;slug&gt;.aliases</code></td><td>Other names people might search for, comma-separated, never shown. Optional per language: add the words people really type, not a translation of the English list.</td></tr><tr><td><code>&lt;slug&gt;.variationNote</code></td><td>How this variation differs from its neighbours, shown under the name.</td></tr><tr><td><code>&lt;slug&gt;.instructions.&lt;n&gt;</code></td><td>One step of how to do the exercise, in order, addressed to the person.</td></tr></tbody></table>',15)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
